            '<span style="color:var(--text-muted)">'+pctLabel+'</span></span>'+
            (pool>0?'<div class="dhcp-util-bar"><div class="dhcp-util-fill" style="width:'+Math.min(100,pct)+'%;background:'+fillColour+'"></div></div>':'')+'</td>'+
        '</tr>';
